let INDEX = null;
export function hdrLookup(crc) {
  if (!INDEX) {
    INDEX = new Map();
    for (const r of HDR_TABLE_DATA.split(";")) {
      const c = r.split(",");
      INDEX.set(parseInt(c[0], 16) >>> 0, { mapper: +c[1], sub: +c[2], prgKB: +c[3], chrKB: +c[4], chrRamKB: +c[5], ramKB: +c[6], region: +(c[7] || 0),
                                            mirr: c[8] === undefined || c[8] === "" ? -1 : +c[8], bat: c[9] === "1" ? 1 : 0 });
    }
  }
  return INDEX.get(crc >>> 0) || null;
}

/* The switches (see THE RULE above); the page's off switches
 * for the two new rules, set by the importer -- web/core.js HEADER_FIX. */
export const HDR_R18 = { noRamRow: true, mirrorRow: true, fcgNoWram: true };   /* (taken after) */
export const HDR_R22 = { batteryRow: true };
const WIRING = ["A11 (horizontal)", "A10 (vertical)", "one-screen 0", "one-screen 1", "four-screen"];

/* Apply the rule above.  h = { nes2, mapper, submapper, prgSize, chrSize,
 * ciram, battery }, dataLen = bytes after header and trainer.  Returns null (no row, or
 * nothing to change) or { mapper, submapper, prgSize, chrSize, chrRam2, ramMin,
 * ramNone, ciram, battery, changed: [text, ...] }. */
export function hdrDecide(h, e, dataLen) {
  if (!e) return null;
  if (h.mapper === 6 || h.mapper === 17) return null;     /* a copier format: never overridden */
  const r = { mapper: h.mapper, submapper: h.submapper, prgSize: h.prgSize, chrSize: h.chrSize,
              chrRam2: 0, ramMin: 0, ramNone: false, ciram: h.ciram, battery: 0, changed: [] };
  if (e.mapper < 0) {                                     /* an IDENTITY-ONLY row: no board fact */
    if (h.nes2 || e.sub < 0 || e.sub === h.submapper) return null;
    r.submapper = e.sub; r.changed.push(`submapper ${h.submapper} -> ${e.sub} (identity row)`);
    return r;
  }
  if (h.nes2) {
    if (e.mapper === h.mapper) return null;
    r.mapper = e.mapper; r.submapper = e.sub >= 0 ? e.sub : 0;
    r.changed.push(`mapper ${h.mapper}.${h.submapper} -> ${r.mapper}.${r.submapper}`);
    return r;
  }
  if (e.mapper !== h.mapper) { r.mapper = e.mapper; r.changed.push(`mapper ${h.mapper} -> ${e.mapper}`); }
  if (e.sub >= 0 && e.sub !== h.submapper) { r.submapper = e.sub; r.changed.push(`submapper ${h.submapper} -> ${e.sub}`); }
  const p = e.prgKB * 1024, c = e.chrKB * 1024;
  if (p && p + c === dataLen && (p !== h.prgSize || c !== h.chrSize)) {
    r.prgSize = p; r.chrSize = c;
    r.changed.push(`program/character ${h.prgSize >> 10}/${h.chrSize >> 10} KB -> ${e.prgKB}/${e.chrKB} KB`);
  }
  if (r.chrSize && e.chrRamKB) r.chrRam2 = e.chrRamKB * 1024;
  /* A board with NO character firmware and more than 8 KB of character RAM
   * (Oeka Kids 32 KB): the size an iNES 1.0 header cannot state. */
  r.chrRamMin = (!r.chrSize && e.chrRamKB > 8) ? e.chrRamKB * 1024 : 0;
  r.ramMin = e.ramKB * 1024;
  /* the row records NO work or save RAM on this board. */
  /* The Bandai FCG boards (16, 159) were excepted until the core answered $6000 with their EEPROM; since
   * it does on the boards whose chip is named (159; 16 with a submapper), the lent RAM is
   * unreachable there, and the rule applies to them as to every board; 16.0 keeps the exception (its board is unknown).
   * HDR_R18.fcgNoWram = false restores the exception (it must match the core switch NES_R18_FCG_NO_WRAM). */
  r.ramNone = HDR_R18.noRamRow && e.ramKB === 0 &&
    (HDR_R18.fcgNoWram ? !(r.mapper === 16 && r.submapper === 0) : (r.mapper !== 16 && r.mapper !== 159));
  /* the row records the wiring and the header disagrees. */
  if (HDR_R18.mirrorRow && e.mirr >= 0 && h.ciram !== undefined && e.mirr !== h.ciram) {
    r.changed.push(`mirroring ${WIRING[h.ciram] ?? h.ciram} -> ${WIRING[e.mirr]}`);
    r.ciram = e.mirr;
  }
  /* the row records a battery and the header's bit is clear. */
  if (HDR_R22.batteryRow && e.bat && h.battery === 0) { r.battery = 1; r.changed.push(`battery bit 0 -> 1`); }
  if (!r.changed.length && !r.chrRam2 && !r.chrRamMin && r.ramMin <= 8192 && !r.ramNone) return null;
  return r;
}

const CRC_T = (() => { const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; }
  return t; })();
export function crc32(bytes, from = 0, to = bytes.length) {
  let c = 0xFFFFFFFF;
  for (let i = from; i < to; i++) c = CRC_T[(c ^ bytes[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}
